using System;using System.Data.SqlClient;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class UsersPage:UserControl{DataGridView g=Ui.Grid();public UsersPage(){var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52};var role=Ui.Button(L.Fa?"تغییر نقش":"Change role",false);role.Click+=ChangeRole;var state=Ui.Button(L.Fa?"فعال/غیرفعال":"Enable / Disable",false);state.Click+=Toggle;bar.Controls.Add(role);bar.Controls.Add(state);Controls.Add(g);Controls.Add(bar);LoadData();}void LoadData(){g.DataSource=Database.Query("SELECT Id,Username,FullName,Email,Role,IsActive,CreatedAt FROM Users ORDER BY Id DESC");}int Id(){return g.CurrentRow==null?0:Convert.ToInt32(g.CurrentRow.Cells["Id"].Value);}void ChangeRole(object s,EventArgs e){int id=Id();if(id==0)return;var m=new ContextMenuStrip();foreach(var r in new[]{"Admin","Recruiter","Employer","Candidate"})m.Items.Add(r,null,(a,b)=>{Database.Exec("UPDATE Users SET Role=@r WHERE Id=@id",new SqlParameter("@r",((ToolStripItem)a).Text),new SqlParameter("@id",id));Database.Audit("RoleChange","User",id.ToString());LoadData();});m.Show(Cursor.Position);}void Toggle(object s,EventArgs e){int id=Id();if(id==0||id==AppSession.UserId)return;Database.Exec("UPDATE Users SET IsActive=CASE WHEN IsActive=1 THEN 0 ELSE 1 END WHERE Id=@id",new SqlParameter("@id",id));Database.Audit("ToggleActive","User",id.ToString());LoadData();}}}